const rimMat = new THREE.LineBasicMaterial({ color: teal, transparent: true, opacity: 0.95 });
function makeCircleLine(y) {
  const pts = [];
  for (let i = 0; i <= 128; i++) {
    const t = (i / 128) * Math.PI * 2;
    pts.push(new THREE.Vector3(radius * Math.cos(t), y, radius * Math.sin(t)));
  }
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), rimMat.clone());
}
const topRim = makeCircleLine(0.55);
