function makeCurveArrow(points, color = 0x111111) {
  const group = new THREE.Group();
  const curve = new THREE.CatmullRomCurve3(points);
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(curve.getPoints(48)), new THREE.LineBasicMaterial({ color }));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.16, 18), new THREE.MeshBasicMaterial({ color }));
  group.add(line, cone);
  group.userData.points = points.map(p => p.clone());
  group.userData.line = line;
  group.userData.cone = cone;
  scene.add(group);
  return group;
}

function updateCurveArrow(group, points) {
  const curve = new THREE.CatmullRomCurve3(points);
  const sampled = curve.getPoints(48);
  group.userData.line.geometry.dispose();
  group.userData.line.geometry = new THREE.BufferGeometry().setFromPoints(sampled);
  const end = sampled[sampled.length - 1];
  const prev = sampled[sampled.length - 4] || sampled[sampled.length - 2];
  const dir = end.clone().sub(prev).normalize();
  group.userData.cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.userData.cone.position.copy(end).sub(dir.clone().multiplyScalar(0.08));
}

