  ]);
  deltaLabel.pos.set(bx - 0.18, 0, bz + 0.02);

  updateCurveArrow(deltaALeader, [
    new THREE.Vector3(1.55, h / 2 + 0.43, 0.38),
    new THREE.Vector3(1.18, h / 2 + 0.42, 0.32),
    new THREE.Vector3(0.43, h / 2 + 0.05, 0.13)
  ]);
  deltaALabel.pos.set(1.58, h / 2 + 0.48, 0.43);

  updateCurveArrow(insideLeader, [
    new THREE.Vector3(-1.55, -h / 2 - 0.18, -0.60),
    new THREE.Vector3(-1.08, -h / 2 - 0.22, -0.48),
    new THREE.Vector3(-0.45, -h / 2 + 0.03, -0.25)
  ]);
  insideLabel.pos.set(-1.73, -h / 2 - 0.20, -0.66);

  if (selectedSurface) updateFluxText(selectedSurface, false);
}

function setFieldRegion(region) {
  currentRegion = region;
  document.getElementById('fieldOutside').classList.toggle('active', region === 'Outside');
  document.getElementById('fieldInside').classList.toggle('active', region === 'Inside');
  if (region === 'Outside') {
    setArrowOpacity(1);
    eLabel.div.style.opacity = '1';
    insideLabel.div.style.opacity = '0.72';
    lowerCap.material.opacity = 0.25;
  } else {
    setArrowOpacity(0.16);
    eLabel.div.style.opacity = '0.22';
    insideLabel.div.style.opacity = '1';
    lowerCap.material.opacity = 0.42;
  }
}

function updateHighlights() {
  highlightTop.visible = selectedSurface === 'top';
  highlightSide.visible = selectedSurface === 'side';
  highlightLower.visible = selectedSurface === 'lower';
}

function updateFluxText(surface, popup = true) {
  selectedSurface = surface;
  updateHighlights();
  let html = '';
  let panel = '';
  let title = '';
  let body = '';
  if (surface === 'top') {
    html = 'Φ<sub>top</sub> = E ΔA';
    panel = '<b>Top cap:</b> Φ<sub>top</sub> = E ΔA. The field is normal to the outside cap.';
    title = 'Top cap flux';
    body = 'Outside the positively charged conductor, the electric field points along the outward normal, so the top cap contributes Φtop = E ΔA.';
    fluxLabel.pos.set(0.98, currentHeight / 2 + 0.22, -0.65);
  } else if (surface === 'side') {
    html = 'Φ<sub>side</sub> → 0 as δ → 0';
    panel = '<b>Side wall:</b> its area is circumference × δ, so its flux vanishes as δ becomes small.';
    title = 'Side-wall flux';
    body = 'The cylindrical side area is proportional to δ. In the thin-pillbox limit it collapses to zero, so the side-wall contribution vanishes.';
    fluxLabel.pos.set(1.12, 0.02, -0.75);
  } else {
    html = 'Φ<sub>lower</sub> = 0';
    panel = '<b>Lower cap:</b> Φ<sub>lower</sub> = 0 because E = 0 inside the conductor.';
    title = 'Lower cap flux';
    body = 'Inside a conductor in electrostatic equilibrium the electric field is zero, so the buried cap contributes no flux.';
    fluxLabel.pos.set(0.90, -currentHeight / 2 - 0.20, -0.67);
  }
  fluxLabel.div.innerHTML = html;
  fluxLabel.div.style.display = '';
  document.getElementById('fluxPanel').innerHTML = panel + '<br><br>Gauss law gives E ΔA = σ ΔA / ε<sub>0</sub>, hence E = σ/ε<sub>0</sub>.';
  if (popup) showPopup(title, body);
}

registerInteractive(topCap, {
  title: 'Top cap ΔA',
  tooltip: 'Click: top cap flux',
