document.getElementById('pillboxHeight').addEventListener('input', (e) => {
  updatePillboxHeight(parseFloat(e.target.value));
});
document.getElementById('fieldOutside').addEventListener('click', () => setFieldRegion('Outside'));
document.getElementById('fieldInside').addEventListener('click', () => setFieldRegion('Inside'));

const demoSteps = [
  {
    title: 'Pillbox straddling the surface',
    narration: 'The cylindrical Gaussian surface crosses the charged conductor surface at point P. The red field arrow is normal to the surface just outside the conductor.',
    state: { pillboxHeight: 1.1, fieldRegion: 'Outside' }
  },
  {
    title: 'Thin the pillbox',
    narration: 'Reducing δ makes the cylindrical side wall collapse toward zero area, while the top cap ΔA remains the same. The flux contribution in the limit comes from the outer cap.',
    state: { pillboxHeight: 0.25, fieldRegion: 'Outside' }
  },
  {
    title: 'Look inside the conductor',
    narration: 'Inside the conductor in electrostatic equilibrium, the field is zero. The buried cap contributes no flux.',
    state: { pillboxHeight: 0.25, fieldRegion: 'Inside' }
  },
  {
    title: 'Choose each Gaussian surface',
    narration: 'Click the top cap, side wall, and lower cap to compare their flux terms: Φtop = E ΔA, Φside tends to zero with δ, and Φlower = 0.',
    state: { pillboxHeight: 0.35, fieldRegion: 'Outside' }
  }
];

let tweenToken = 0;
window.goToStep = function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  tweenToken++;
  const token = tweenToken;
  const start = currentHeight;
  const end = step.state.pillboxHeight;
  const t0 = performance.now();
  const dur = 650;
  setFieldRegion(step.state.fieldRegion);
  showPopup(step.title, step.narration);
  function tick(now) {
    if (token !== tweenToken) return;
    const u = Math.min(1, (now - t0) / dur);
    const eased = 1 - Math.pow(1 - u, 3);
    const h = start + (end - start) * eased;
    document.getElementById('pillboxHeight').value = h;
    updatePillboxHeight(h);
    if (u < 1) requestAnimationFrame(tick);
    else {
      document.getElementById('pillboxHeight').value = end;
      updatePillboxHeight(end);
      if (i === 3) updateFluxText('top', false);
    }
  }
  requestAnimationFrame(tick);
};

for (let i = 0; i < 4; i++) {
  document.getElementById(`step${i}`).addEventListener('click', () => window.goToStep(i));
}

